{
  "revised_script": {
    "cold_open": "The salt-crusted glass of the Blackwood Reach lighthouse groaned under the weight of the gale.",
    "question": "Why does the great lantern pulse with a steady, amber warmth when the oil has been dry for decades?",
    "journey": "Elias climbed the spiral stairs, his boots clicking against iron treads slick with condensation. He carried a heavy brass lantern, though he knew its flame was useless against the supernatural glow above. Outside, the Atlantic thrashed against the foundation, sending plumes of spray into the gallery. He reached the summit, his breath hitching in the freezing air. The gears of the great lens were frozen, yet they began to hum, turning with a rhythmic, metallic heartbeat.",
    "discovery": "In the center of the rotating lens, a small, weathered leather glove sat perched on the pedestal. It was the keeper’s glove, still holding the faint, lingering scent of tobacco and old wool, illuminated by a flame that cast no smoke.",
    "emotional_turn": "Elias reached out, his fingers trembling. He didn't see a ghost; he felt a sudden, overwhelming sense of duty—a heavy mantle of responsibility passed from one tired soul to another.",
    "payoff": "The light didn't just shine; it anchored the coastline. As the gears locked into a perfect, steady rotation, the frantic pulse of the storm seemed to settle into a rhythmic lullaby.",
    "after_image": "The next morning, the lighthouse stood silent, but the keeper's glove remained warm."
  },
  "edits": [
    {
      "where": "cold_open",
      "change": "Replaced 'There is an old lighthouse' with 'The salt-crusted glass... groaned'.",
      "why": "Repaired the 'Flat Narrative' flaw by establishing atmosphere and sensory detail immediately."
    },
    {
      "where": "question",
      "change": "Shifted from 'it is not mysterious' to a specific inquiry about the amber warmth.",
      "why": "Repaired the 'Lack of Conflict' flaw; the original draft dismissed the mystery instead of posing it as a narrative hook."
    },
    {
      "where": "journey",
      "change": "Added the sensory details of the spiral stairs, the hum of gears, and the physical sensation of the storm.",
      "why": "Repaired 'Passive Observation' by placing the protagonist inside the action rather than watching from a distance."
    },
    {
      "where": "discovery",
      "change": "Introduced the tobacco-scented glove as a physical anchor.",
      "why": "Repaired 'Vague Imagery' by providing a concrete, tactile object to represent the keeper's presence."
    },
    {
      "where": "payoff",
      "change": "Changed the ending from 'everything is calm' to the light 'anchoring' the coast.",
      "why": "Repaired 'Weak Resolution' by ensuring the central question (the light's purpose) received a thematic payoff."
    }
  ],
  "self_scores": {
    "curiosity_hold": 9,
    "midpoint_turn": 8,
    "payoff_resolution": 9,
    "final_image_stick": 10
  }
}
